from pathlib import Path
import hashlib,json,os,subprocess,sys,tempfile
root=Path('/Users/lanxingcan/Workspace/zstdoxize');sys.path.insert(0,str(root/'scripts'));children=[]
def forbidden(*args,**kwargs):children.append('blocked');raise RuntimeError('child creation forbidden during projection')
subprocess.Popen=forbidden
for name in ['system','fork','forkpty','posix_spawn','posix_spawnp','spawnl','spawnle','spawnlp','spawnlpe','spawnv','spawnve','spawnvp','spawnvpe','execl','execle','execlp','execlpe','execv','execve','execvp','execvpe']:
 if hasattr(os,name):setattr(os,name,forbidden)
import pack_greedy_frame_trajectories as m
files=m.projection()
for name,data in files.items():
 if (m.DESTINATION/name).read_bytes()!=data:raise ValueError('projection differs: '+name)
rejected=[]
with tempfile.TemporaryDirectory(prefix='zstdoxide-greedy-projection-') as directory:
 p=Path(directory);target=p/'fresh';m.publish(files,target)
 for name,data in files.items():
  if (target/name).read_bytes()!=data:raise ValueError('fresh publication differs')
 for label,path,contents in [('existing',target,files),('bad_names',p/'bad',{'../outside':b'x'}),('symlink',p/'alias',files)]:
  if label=='symlink':path.symlink_to(target,target_is_directory=True)
  try:m.publish(contents,path)
  except ValueError:rejected.append(label)
  else:raise ValueError('publication preflight accepted: '+label)
 if (p/'bad').exists() or (p/'outside').exists():raise ValueError('failed preflight wrote destination')
 if {n:(target/n).read_bytes() for n in files}!=files:raise ValueError('existing output changed')
if children or len(rejected)!=3:raise ValueError('control outcome')
print(json.dumps({'python':sys.version,'optimization':sys.flags.optimize,'child_attempts':len(children),'projected_bytes':len(files['cases.bin']),'projected_sha256':hashlib.sha256(files['cases.bin']).hexdigest(),'rejected_controls':rejected,'generator_sha256':hashlib.sha256(Path(m.__file__).read_bytes()).hexdigest()},sort_keys=True))
